TITULO_POR_DEFECTO = 'Bienvenido a nuestra tienda'


def copiar_textos_de_la_portada(apps, schema_editor):
    """Las fotos que ya existían toman los textos de la portada, así la tienda se ve igual que antes."""
    FotoBanner = apps.get_model('ventas', 'FotoBanner')
    for foto in FotoBanner.objects.select_related('configuracion').filter(titulo=''):
        config = foto.configuracion
        foto.antetitulo = (config.subtitulo_bienvenida or '').strip()[:200]
        foto.titulo = ((config.texto_bienvenida or '').strip() or TITULO_POR_DEFECTO)[:300]
        foto.texto = (config.texto_landing or '').strip()[:1000]
        foto.save(update_fields=['antetitulo', 'titulo', 'texto'])


